from dataclasses import dataclass
from typing import Any, Callable, Optional, Union, Literal, Sequence

@dataclass(unsafe_hash=True)
class Depends:
    dependency: Optional[Callable[..., Any]] = None
    use_cache: bool = True
    scope: Union[Literal["function", "request"], None] = None

@dataclass(unsafe_hash=True)
class Security(Depends):
    scopes: Optional[Sequence[str]] = None

    def __post_init__(self):
        if self.scopes is not None:
            self.scopes = tuple(self.scopes)

d1 = Depends(dependency=lambda x: x)
print(f"Depends hashable: {hash(d1)}")

s1 = Security(dependency=lambda x: x, scopes=["read"])
